changeSet.sql:
ALTER TABLE zc_dead_letter
  ADD CONSTRAINT fk_zc_dead_letter_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_dead_letter
  ADD CONSTRAINT fk_zc_dead_letter_operational_task FOREIGN KEY (tenant_id, operational_task_id)
    REFERENCES zc_task (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_idempotency_key_tenant ON zc_idempotency_key
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_integration_outbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_integration_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_integration_outbox_tenant ON zc_integration_outbox
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_integration_inbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_integration_inbox FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_integration_inbox_tenant ON zc_integration_inbox
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_dead_letter ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_dead_letter FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_dead_letter_tenant ON zc_dead_letter
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_idempotency_key_tenant ON zc_idempotency_key;
ALTER TABLE zc_idempotency_key NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_idempotency_key DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_integration_outbox_tenant ON zc_integration_outbox;
ALTER TABLE zc_integration_outbox NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_integration_outbox DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_integration_inbox_tenant ON zc_integration_inbox;
ALTER TABLE zc_integration_inbox NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_integration_inbox DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_dead_letter_tenant ON zc_dead_letter;
ALTER TABLE zc_dead_letter NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_dead_letter DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_idempotency_key TO zc_app;
GRANT SELECT, DELETE ON zc_idempotency_key TO zc_housekeeping;
GRANT USAGE ON SEQUENCE zc_idempotency_key_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_integration_outbox TO zc_app;
GRANT USAGE ON SEQUENCE zc_integration_outbox_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_integration_inbox TO zc_app;
GRANT USAGE ON SEQUENCE zc_integration_inbox_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_dead_letter TO zc_app;
GRANT USAGE ON SEQUENCE zc_dead_letter_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_idempotency_key FROM zc_app, zc_housekeeping;
REVOKE USAGE ON SEQUENCE zc_idempotency_key_id_seq FROM zc_app;
REVOKE ALL ON zc_integration_outbox FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_integration_outbox_id_seq FROM zc_app;
REVOKE ALL ON zc_integration_inbox FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_integration_inbox_id_seq FROM zc_app;
REVOKE ALL ON zc_dead_letter FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_dead_letter_id_seq FROM zc_app;
